  if (!cur) { if (authH) { authId = ""; authH.close(false); } return; }
  if (!authH) { const h = fsOpen({ onClose: () => { if (authId) AUTH_HID.add(authId); authId = ""; if (authH === h) authH = null; } }); authH = h; }
  if (authId === cur.id) return;
