  const wrap = el("div", { class: "pmv-ed" });
  const show = () => clear(wrap).append(el("button", { type: "button", class: `pmv-edit ${cls}${value ? "" : " empty"}`, title: "눌러서 고쳐요", "aria-label": `${label} 고치기`, onclick: edit, text: value || placeholder }));
