  const rows = [...tl.querySelectorAll(":scope > [data-ts]")], fresh = rows.length ? freshKeys(NT_SEEN, rows.map(r => r.dataset.ts)) : new Set(), was = ntNewest;
  for (const r of rows) if (r.dataset.ts > ntNewest) ntNewest = r.dataset.ts;
