    if (NT.gone.has(row.dataset.ts)) { row.hidden = true; continue; }
    if (row.querySelector(".al-x")) continue;
    const e = ts("alert").msgs.find(x => x.ts === row.dataset.ts), n = e && ntOfEvent(e);
    if (!n || !n.id || ntNeeds(n) || ntOpenDec(n)) continue;
