  if (b.hidden) return;
  clear(b).append(icon("list"), el("span", { class: "tx", text: TR.groups.length > 1 ? `답장 대기 ${total}건 · ${TR.groups.length}곳` : `${g.label} 대기 ${g.count}건` }), el("span", { class: "go", text: "빠르게 처리" }));
