  TR.i = Math.max(0, ref ? TR.items.findIndex(c => c.ref === ref) : 0);
  const h = fsOpen({ label: `${TR.label} 빠른 처리`, cls: "tall tr", onClose: () => { if (TR.h === h) TR.h = null; document.removeEventListener("keydown", trKey); trBanner(); } });
  TR.h = h;
